-- Private storage buckets. Files are only ever served through short-lived signed
-- URLs generated by server code after an authorization check.
-- (Guarded so the migration also runs on plain Postgres used for local tests.)
do $$
begin
  if exists (select 1 from information_schema.tables where table_schema = 'storage' and table_name = 'buckets') then
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values
      ('quote-photos', 'quote-photos', false, 8388608, array['image/jpeg', 'image/png', 'image/webp', 'image/heic']),
      ('job-photos', 'job-photos', false, 12582912, array['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
    on conflict (id) do nothing;
  end if;
end $$;
